import fs from 'node:fs';
import path from 'node:path';
const root=process.argv[2]||'engine';
function patch(file,before,after){const p=path.join(root,file),s=fs.readFileSync(p,'utf8').split(String.fromCharCode(13,10)).join(String.fromCharCode(10));if(!s.includes(before))throw Error('Upstream source changed: '+file);fs.writeFileSync(p,s.replace(before,after));}
fs.writeFileSync(path.join(root,'src/nacent-slicer-bridge.ts'),"import type { AppContext } from '@core/types';\nimport { estimateSlaHours } from './nacent-slicer-budget';\nimport * as THREE from 'three';\nimport {modelBounds} from '@core/nacent-measure-math';\n\n/** Only numeric slice results cross the bridge. STL geometry stays in this browser. */\nexport function mountNacentBridge(ctx: AppContext): void {\n  const token = new URLSearchParams(location.hash.slice(1)).get('nacent');\n  const recipient:Window|null = parent!==window ? parent : window.opener as Window|null;\n  const stamps = new Map<string, {layerHeight:number; slicedAt:string}>();\n  const bar = document.createElement('section');\n  bar.id = 'nacent-budget-bar';\n  bar.innerHTML = `<div><b>Nacent · Slicer para orçamento</b><span>Carregar → Preparar → Usar volumes direto · Fatiar é opcional</span></div>\n    <details><summary>Parâmetros adicionais de tempo</summary><label>Velocidade de retorno (mm/s)<input id=\"nacent-retract\" type=\"number\" min=\"0.01\" step=\"0.1\" value=\"3\"></label><label>Espera por camada (s)<input id=\"nacent-rest\" type=\"number\" min=\"0\" step=\"0.1\" value=\"1\"></label><small>Exposição, camadas base, elevação e velocidade de subida são configuradas em Fatiar. Ajuste à sua resina; o tempo é estimado.</small></details>\n    <button id=\"nacent-quick-use\" type=\"button\">Usar peça + suportes · sem fatiar →</button><button id=\"nacent-use\" type=\"button\">Usar fatiamento →</button><p id=\"nacent-feedback\" role=\"status\">Estimativa rápida pela geometria da peça e dos suportes. Fatiar refina o consumo por camada. Projeto 3D salvo neste navegador.</p>`;\n  document.body.prepend(bar);\n  const style = document.createElement('style');\n  style.textContent = `body{padding-top:78px;box-sizing:border-box}#nacent-budget-bar{position:fixed;top:0;left:0;right:0;z-index:10000;background:#142b25;color:#edf7f1;display:flex;align-items:center;gap:14px;padding:10px 16px;flex-wrap:wrap;font:12px system-ui;box-shadow:0 1px 10px #0004}#nacent-budget-bar b{display:block;font-size:14px}#nacent-budget-bar span{display:block;margin-top:4px;color:#cad9d1}#nacent-budget-bar button{background:#ccf37b;border:0;padding:10px 16px;border-radius:8px;font-weight:700;cursor:pointer;margin-left:auto}#nacent-budget-bar p{width:100%;margin:0;font-size:11px;color:#b7cbbf}#nacent-budget-bar details[open]{position:absolute;top:8px;right:230px;background:#142b25;padding:12px;border:1px solid #708478;border-radius:8px;width:290px}#nacent-budget-bar label{display:block;margin:8px 0}#nacent-budget-bar input{width:80px;margin-left:8px;color:#fff;background:#263e33;border:1px solid #8a9d92;padding:4px}#nacent-budget-bar small{display:block;line-height:1.5}#nacent-budget-bar summary{cursor:pointer}#nacent-budget-bar button:disabled{opacity:.5}@media(max-width:700px){body{padding-top:130px}#nacent-budget-bar{gap:7px}#nacent-budget-bar span{font-size:10px}#nacent-budget-bar details[open]{right:10px;top:40px}#nacent-budget-bar button{padding:8px}}`;\n  document.head.append(style);\n  const undoButton=document.createElement('button');undoButton.id='nacent-undo';undoButton.type='button';undoButton.title='Desfazer última ação (Ctrl+Z)';undoButton.setAttribute('aria-label','Desfazer (Ctrl+Z)');undoButton.textContent='↶ Desfazer';\n  document.getElementById('toolbar-right')?.prepend(undoButton);\n  undoButton.addEventListener('click',()=>{ctx.viewer.undo();if(ctx.viewer.objects.length===1)ctx.viewer.selectObject(ctx.viewer.objects[0].id);ctx.viewer.requestRender();});\n  for(const name of ['undo','redo'] as const){const original=ctx.viewer[name].bind(ctx.viewer);ctx.viewer[name]=()=>{const selected=ctx.viewer.selected.map(o=>o.id);original();const existing=selected.filter(id=>ctx.viewer.objects.some(o=>o.id===id));if(existing.length)ctx.viewer.selectObjects(existing);ctx.viewer.requestRender();};}\n  style.textContent+='#nacent-undo{border:1px solid var(--border);border-radius:6px;background:var(--surface-2);color:var(--text);padding:7px 10px;cursor:pointer;font:12px system-ui}#nacent-use{background:#29473b!important;color:#e5f1e8!important;border:1px solid #5b7868!important;margin-left:0!important}#nacent-quick-use{margin-left:auto!important}';\n  // Numeric transform panels must record history just like dragging the gizmo.\n  const transforms=ctx.viewer as unknown as Record<string,(...args:unknown[])=>unknown>;\n  for(const name of ['scaleSelectionBy','rotateSelectionBy','translateSelectionTo','setElevation']){\n    const original=transforms[name].bind(ctx.viewer);\n    transforms[name]=(...args:unknown[])=>{if(ctx.viewer.selected.length)ctx.viewer._saveUndoState?.();return original(...args);};\n  }\n  (ctx.viewer.transformControl as {addEventListener:(type:string,callback:()=>void)=>void}).addEventListener('mouseDown',()=>{if(ctx.viewer.selected.length)ctx.viewer._saveUndoState?.();});\n  // The upstream two time summaries use a different motion model. Nacent's\n  // configurable estimate is displayed in the bridge; avoid contradictory totals.\n  style.textContent += '#print-time-estimate,#print-estimate .estimate-row:last-child{display:none!important}';\n  style.textContent += `body{padding-top:var(--nacent-bar,78px)}#app{height:calc(100dvh - var(--nacent-bar,78px));min-height:0}#sidebar{top:calc(48px + var(--nacent-bar,78px))}`;\n  new ResizeObserver(()=>document.documentElement.style.setProperty('--nacent-bar',`${bar.getBoundingClientRect().height}px`)).observe(bar);\n  const feedback = document.getElementById('nacent-feedback')!;\n  const read = (id:string):number => Number((document.getElementById(id) as HTMLInputElement)?.value);\n  document.getElementById('nacent-quick-use')!.addEventListener('click',()=>{\n    try {\n      if(!recipient||!token)throw Error('Abra o slicer pelo botão do lote na calculadora Nacent.');\n      if(document.getElementById('selected-printer-name')?.textContent!=='Elegoo Saturn 3 Ultra')throw Error('Selecione a Elegoo Saturn 3 Ultra.');\n      const info=ctx.viewer.getOverallInfo();if(!info)throw Error('Carregue uma peça primeiro.');\n      const modelVolumeMl=info.modelVolume/1000,supportVolumeMl=info.supportVolume/1000;\n      const volumeMl=modelVolumeMl+supportVolumeMl;\n      if(!Number.isFinite(volumeMl)||volumeMl<=0)throw Error('Não foi possível estimar o volume desta geometria.');\n      const meshes=ctx.viewer.objects.flatMap(o=>[o.mesh,o.supportsMesh,o.bracingMesh].filter(Boolean)) as unknown as THREE.Object3D[];\n      const layerHeight=read('layer-height'),height=modelBounds(meshes).max.y;\n      if(!(layerHeight>0)||!Number.isFinite(height)||height<=0)throw Error('Confira a altura da peça e a altura de camada.');\n      const layerCount=Math.max(1,Math.ceil(height/layerHeight));\n      const timing={normalExposure:read('normal-exposure'),bottomExposure:read('bottom-exposure'),bottomLayers:read('bottom-layers'),liftHeight:read('lift-height'),liftSpeed:read('lift-speed'),retractSpeed:read('nacent-retract'),restSeconds:read('nacent-rest')};\n      const hours=estimateSlaHours(layerCount,timing);\n      const payload={version:1,engine:'SliceLab',printer:'saturn-3-ultra',method:'geometry',modelVolumeMl,supportVolumeMl,volumeMl,hours,layerCount,layerHeight,timing,modelNames:ctx.viewer.objects.map(o=>o.mesh.name),slicedAt:''};\n      recipient.postMessage({type:'nacent-slicer-result',token,payload},location.origin);\n      feedback.textContent='Peça e suportes enviados diretamente ao orçamento, sem fatiar.';\n    }catch(e){feedback.textContent=e instanceof Error?e.message:'Não foi possível estimar o volume.';}\n  });\n  ctx.viewer.canvas.addEventListener('nacent-slice-ready', ((e:CustomEvent<{plateId:string; layerHeight:number}>)=>{\n    stamps.set(e.detail.plateId, {layerHeight:e.detail.layerHeight,slicedAt:new Date().toISOString()});\n    feedback.textContent = 'Fatiamento concluído. Confira os parâmetros de tempo e use no orçamento.';\n  }) as EventListener);\n  document.getElementById('nacent-use')!.addEventListener('click', ()=>{\n    try {\n      const plate = ctx.project.plates.find(p=>p.id===ctx.project.activePlateId);\n      const stamp = plate && stamps.get(plate.id);\n      if (!plate?.slicedVolumes || !plate.slicedLayerCount || !stamp) throw Error('Clique em Fatiar para calcular o volume da plate atual.');\n      if (read('layer-height') !== stamp.layerHeight) throw Error('A altura de camada mudou. Fatie novamente.');\n      if (document.getElementById('selected-printer-name')?.textContent !== 'Elegoo Saturn 3 Ultra') throw Error('Selecione a Elegoo Saturn 3 Ultra e fatie novamente.');\n      const timing = {normalExposure:read('normal-exposure'),bottomExposure:read('bottom-exposure'),bottomLayers:read('bottom-layers'),liftHeight:read('lift-height'),liftSpeed:read('lift-speed'),retractSpeed:read('nacent-retract'),restSeconds:read('nacent-rest')};\n      const hours = estimateSlaHours(plate.slicedLayerCount,timing);\n      const payload = {version:1,engine:'SliceLab',printer:'saturn-3-ultra',method:'slice',modelVolumeMl:plate.slicedVolumes.model/1000,supportVolumeMl:plate.slicedVolumes.supports/1000,volumeMl:plate.slicedVolumes.total/1000,hours,layerCount:plate.slicedLayerCount,layerHeight:stamp.layerHeight,timing,modelNames:plate.objects.map(o=>o.mesh.name),slicedAt:stamp.slicedAt};\n      if (!(payload.volumeMl>0) || !Number.isFinite(payload.volumeMl)) throw Error('Volume vazio ou inválido. Confira a geometria e fatie novamente.');\n      if (!recipient || !token) throw Error('Abra o slicer pelo botão do lote na calculadora Nacent.');\n      recipient.postMessage({type:'nacent-slicer-result',token,payload},location.origin);\n      feedback.textContent = `${payload.volumeMl.toFixed(3)} ml · ${hours.toFixed(2)} h estimadas. Confira e aplique na Nacent.`;\n    } catch(e) {feedback.textContent=e instanceof Error?e.message:'Não foi possível usar o resultado.';}\n  });\n  const invalidate = ():void => {if(recipient&&token)recipient.postMessage({type:'nacent-slicer-invalid',token},location.origin);};\n  for(const name of ['mesh-changed','paint-changed','plate-changed'])ctx.viewer.canvas.addEventListener(name,invalidate);\n  document.addEventListener('change',invalidate);\n  // Translate the essential static workflow while preserving all engine controls.\n  const words:Record<string,string> = {'Plate':'Plate','Orient':'Orientar','Modify':'Modificar','Supports':'Suportes','Inspect':'Inspecionar','Slice':'Fatiar','Load':'Carregar','Export…':'Exportar…','Basic':'Básico','Advanced':'Avançado','Auto-Generate':'Gerar suportes','Hollow':'Hollow / Ocar','Layer Height':'Altura de camada','Normal Exposure':'Exposição normal','Bottom Layers':'Camadas base','Bottom Exposure':'Exposição base','Lift Height':'Elevação','Lift Speed':'Velocidade de subida','Total Time':'Tempo estimado'};\n  Object.assign(words,{'Load Model':'Carregar modelo','Browse Model File…':'Escolher arquivo STL…','Sample Models':'Modelos de exemplo','Resin Calibration':'Calibração de resina','Test pillars, holes & overhangs':'Teste de pilares, furos e saliências','Transform':'Transformar','Move':'Mover','Size':'Tamanho','Rotate':'Girar','Scale':'Escala','Layout':'Organizar plate','Auto Arrange':'Organizar automaticamente','Drop to Bed':'Colocar na base','Fill Platform':'Preencher plate','Duplicate':'Duplicar','Delete Selected':'Excluir seleção','Clear All':'Limpar plate','Summary':'Resumo','Layers':'Camadas','Height':'Altura','Model':'Modelo','Total':'Total','Normal Exposure (s)':'Exposição normal (s)','Bottom Exposure (s)':'Exposição base (s)','Bottom Layers':'Camadas base','Lift Height (mm)':'Elevação (mm)','Lift Speed (mm/s)':'Velocidade de subida (mm/s)','Layer Height (mm)':'Altura de camada (mm)','Slice Plate':'Fatiar plate','Slice All Plates':'Fatiar todas as plates','Surface':'Resina / superfície','Export a print file':'Usar resultado no orçamento','Load a model':'Carregar modelo','Orient it':'Orientar peça','Generate supports':'Gerar suportes','Slice a plate':'Fatiar plate','GETTING STARTED':'COMO COMEÇAR','Z Elevation (mm)':'Elevação da peça (mm)'});\n  const translate=(root:Node):void=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);for(let n=walker.nextNode();n;n=walker.nextNode()){const key=n.textContent?.trim()??'';if(words[key])n.textContent=words[key];}};\n  const appRoot=document.getElementById('app')!;translate(appRoot);\n  new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)translate(node);}).observe(appRoot,{childList:true,subtree:true});\n  document.title='Nacent — Slicer Saturn 3 Ultra';\n}\n");
fs.writeFileSync(path.join(root,'src/nacent-slicer-budget.js'),"// Time is a configurable estimate, independent from the GPU volume calculation.\nexport function estimateSlaHours(layers, p) {\n  if (!Number.isInteger(layers) || layers < 1) throw Error('Fatie o modelo antes de calcular o tempo.');\n  for (const key of ['normalExposure','bottomExposure','liftHeight','liftSpeed','retractSpeed','restSeconds']) {\n    if (!Number.isFinite(p[key]) || p[key] < 0) throw Error('Confira os parâmetros de tempo.');\n  }\n  if (!Number.isInteger(p.bottomLayers) || p.bottomLayers < 0 || p.liftSpeed <= 0 || p.retractSpeed <= 0) throw Error('Confira as camadas base e as velocidades.');\n  const bottom = Math.min(layers, p.bottomLayers);\n  const motion = p.liftHeight / p.liftSpeed + p.liftHeight / p.retractSpeed + p.restSeconds;\n  return (bottom * p.bottomExposure + (layers - bottom) * p.normalExposure + layers * motion) / 3600;\n}\n\nexport function validateSlicerImport(data) {\n  if (!data || data.version !== 1 || data.engine !== 'SliceLab' || data.printer !== 'saturn-3-ultra') throw Error('Use o perfil Elegoo Saturn 3 Ultra.');\n  if (!Number.isFinite(data.volumeMl) || data.volumeMl <= 0 || data.volumeMl > 100000) throw Error('O slicer não retornou um volume válido.');\n  if (!Number.isInteger(data.layerCount) || data.layerCount < 1 || data.layerCount > 100000) throw Error('Quantidade de camadas inválida.');\n  if (!Number.isFinite(data.layerHeight) || data.layerHeight <= 0 || data.layerHeight > 1) throw Error('Altura de camada inválida.');\n  const hours = estimateSlaHours(data.layerCount, data.timing);\n  if (hours > 10000) throw Error('Confira o tempo estimado.');\n  const method=data.method??'slice';if(!['slice','geometry'].includes(method))throw Error('Origem do volume inválida.');\n  let modelVolumeMl=null,supportVolumeMl=null;\n  if(data.modelVolumeMl!==undefined||data.supportVolumeMl!==undefined){\n    modelVolumeMl=data.modelVolumeMl;supportVolumeMl=data.supportVolumeMl;\n    if(!Number.isFinite(modelVolumeMl)||modelVolumeMl<0||!Number.isFinite(supportVolumeMl)||supportVolumeMl<0||Math.abs(modelVolumeMl+supportVolumeMl-data.volumeMl)>Math.max(.00001,data.volumeMl*.000001))throw Error('Confira os volumes da peça e dos suportes.');\n  }\n  if(method==='geometry'&&modelVolumeMl===null)throw Error('A estimativa rápida precisa separar peça e suportes.');\n  return {version:1, engine:'SliceLab', printer:'saturn-3-ultra', volumeMl:data.volumeMl, hours,method,modelVolumeMl,supportVolumeMl,\n    layerCount:data.layerCount, layerHeight:data.layerHeight, timing:{...data.timing},\n    modelNames:(Array.isArray(data.modelNames)?data.modelNames:[]).slice(0,500).map(s=>String(s).slice(0,200)),\n    slicedAt:typeof data.slicedAt==='string'?data.slicedAt.slice(0,40):'', importedAt:new Date().toISOString()};\n}\n");
fs.writeFileSync(path.join(root,'src/features/scene-viewer/measure.ts'),"import * as THREE from 'three';\nimport type {AppContext} from '@core/types';\nimport {modelBounds,orthogonalToBase,printerDimensions,proportionalScaleFactor} from '@core/nacent-measure-math';\n\ntype RulerMode='points'|'base';\nexport function mountMeasureTool(ctx:AppContext):void {\n  const {viewer}=ctx,canvas=viewer.canvas;\n  const scene=viewer.scene as THREE.Scene,camera=viewer.camera as THREE.Camera;\n  const viewport=document.getElementById('viewport-container')!;\n  const toolbar=document.getElementById('left-toolbar')!;\n  const button=document.createElement('button');button.className='tool-btn';button.id='nacent-ruler-btn';button.type='button';button.title='Régua: ponto a ponto ou ponto até a baseplate';button.setAttribute('aria-label','Régua');button.setAttribute('aria-pressed','false');\n  button.innerHTML='<svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"12\" rx=\"2\"/><path d=\"M7 6v5m4-5v3m4-3v5m4-5v3\"/></svg><span>Régua</span>';\n  toolbar.prepend(button);\n  const hud=document.createElement('section');hud.id='nacent-dimensions';hud.setAttribute('aria-label','Dimensões da peça');\n  hud.innerHTML='<b id=\"nacent-size-scope\">Dimensões da peça</b><div>'+(['width','length','height'] as const).map((key,i)=>`<label>${['Largura (X)','Comprimento (Y)','Altura (Z)'][i]}<span class=\"nacent-size-field\"><input id=\"nacent-size-${key}\" type=\"number\" min=\"0.001\" step=\"any\" aria-label=\"${['Largura','Comprimento','Altura'][i]} (mm)\" disabled><span>mm</span></span></label>`).join('')+'</div><small id=\"nacent-size-hint\" aria-live=\"polite\">Selecione uma peça para editar · escala proporcional</small>';\n  viewport.append(hud);\n  const panel=document.createElement('section');panel.id='nacent-ruler-panel';panel.hidden=true;\n  panel.innerHTML='<header><b>📏 Régua</b><button type=\"button\" id=\"nacent-ruler-close\" aria-label=\"Fechar régua\">×</button></header><div class=\"nacent-ruler-modes\"><button type=\"button\" id=\"nacent-ruler-points\" aria-pressed=\"true\">Ponto a ponto</button><button type=\"button\" id=\"nacent-ruler-base\" aria-pressed=\"false\">Ponto até a baseplate</button></div><p id=\"nacent-ruler-help\">Clique no primeiro ponto da peça.</p><output id=\"nacent-ruler-value\" aria-live=\"polite\">—</output><small id=\"nacent-ruler-axes\"></small><footer><button type=\"button\" id=\"nacent-ruler-clear\">Nova medição</button><span>Alt + arrastar: navegar · Esc: sair</span></footer>';\n  viewport.append(panel);\n  const style=document.createElement('style');\n  style.textContent=`#nacent-dimensions,#nacent-ruler-panel{position:absolute;left:104px;z-index:55;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:10px;box-shadow:0 4px 18px #0002;font:12px system-ui}#nacent-dimensions{top:12px;padding:10px 12px;max-width:calc(100% - 120px);pointer-events:none}#nacent-dimensions b{font-size:11px;color:var(--text-dim)}#nacent-dimensions>div{display:flex;gap:18px;margin:6px 0}#nacent-dimensions strong{display:block;font-size:16px;margin-top:3px;color:var(--text)}#nacent-dimensions small{font-size:10px;color:var(--text-dim)}#nacent-ruler-panel{top:116px;padding:12px;width:330px;max-width:calc(100% - 120px)}#nacent-ruler-panel header{display:flex;justify-content:space-between;align-items:center}#nacent-ruler-panel button{border:1px solid var(--border);background:var(--surface-2);color:var(--text);border-radius:6px;padding:7px;cursor:pointer;font:11px system-ui}#nacent-ruler-close{font-size:16px!important;padding:2px 8px!important}.nacent-ruler-modes{display:flex;gap:6px;margin-top:10px}.nacent-ruler-modes button{flex:1}.nacent-ruler-modes button[aria-pressed=true]{background:#c7ef7b!important;color:#173126!important}#nacent-ruler-help{margin:10px 0;font-size:12px}#nacent-ruler-value{display:block;font-size:24px;font-weight:700;color:var(--accent);margin:6px 0}#nacent-ruler-axes{display:block;color:var(--text-dim);line-height:1.5}#nacent-ruler-panel footer{display:flex;align-items:center;gap:8px;margin-top:10px}#nacent-ruler-panel footer span{font-size:10px;color:var(--text-dim)}.nacent-dimension-tag{position:absolute;z-index:30;pointer-events:none;background:#153329e8;color:#ddfbab;font:600 11px system-ui;border-radius:4px;padding:3px 5px;white-space:nowrap}#nacent-ruler-btn.active{background:#c7ef7b;color:#173126}@media(max-width:700px){#nacent-dimensions,#nacent-ruler-panel{left:86px;max-width:calc(100% - 96px)}#nacent-dimensions>div{gap:9px}#nacent-dimensions strong{font-size:13px}#nacent-dimensions span{font-size:10px}#nacent-ruler-panel{top:120px}}`;\n  document.head.append(style);\n  style.textContent+='#nacent-dimensions{pointer-events:auto}#nacent-dimensions>div{gap:10px}#nacent-dimensions label{min-width:0;flex:1;font-size:11px}.nacent-size-field{display:flex;align-items:center;gap:3px;margin-top:4px}.nacent-size-field input{width:76px;min-width:0;padding:5px 4px;border:1px solid var(--border);border-radius:5px;background:var(--surface-2);color:var(--text);font:600 14px system-ui}.nacent-size-field input:focus{outline:2px solid var(--accent);outline-offset:1px}.nacent-size-field input:disabled{opacity:.65}.nacent-size-field>span{font-size:10px;color:var(--text-dim)}#nacent-ruler-panel{top:126px}@media(max-width:700px){.nacent-size-field input{width:63px;font-size:12px}#nacent-dimensions label{font-size:10px}#nacent-ruler-panel{top:126px}}';\n  const dimensionInputs=(['width','length','height'] as const).map(key=>({key,input:document.getElementById('nacent-size-'+key) as HTMLInputElement}));\n  const sizeHint=document.getElementById('nacent-size-hint')!;\n  for(const {key,input} of dimensionInputs){\n    input.addEventListener('change',()=>{\n      if(viewer.selected.length!==1){updateDimensions();return;}\n      const box=modelBounds(viewer.selected.map(o=>o.mesh as unknown as THREE.Object3D));\n      try {\n        const factor=proportionalScaleFactor(printerDimensions(box)[key],input.valueAsNumber);\n        if(Math.abs(factor-1)>1e-10){viewer.scaleSelectionBy({x:factor,y:factor,z:factor});}\n        reset();updateDimensions();sizeHint.textContent='Escala proporcional aplicada · proporções preservadas';\n      }catch(error){updateDimensions();sizeHint.textContent=(error as Error).message;}\n    });\n    input.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();input.blur();}if(e.key==='Escape'){e.preventDefault();updateDimensions();input.blur();}});\n  }\n  for(const name of ['pointerdown','pointerup','click'])hud.addEventListener(name,e=>e.stopPropagation());\n  // Retire the old visibility-driven tool, which conflicted with normal selection.\n  const oldPanel=document.getElementById('measure-panel');if(oldPanel)oldPanel.remove();\n  let active=false,mode:RulerMode='points',first:THREE.Vector3|null=null,complete=false;\n  let gesture:{x:number;y:number;pointerId:number}|null=null;\n  let rulerGeometry:THREE.Object3D[]=[];\n  let dimensionsGeometry:THREE.Object3D[]=[];\n  const dimensionTags:{element:HTMLSpanElement;position:THREE.Vector3}[]=[];\n  const help=document.getElementById('nacent-ruler-help')!,value=document.getElementById('nacent-ruler-value')!,axes=document.getElementById('nacent-ruler-axes')!;\n  function dispose(items:THREE.Object3D[]):void {for(const item of items){scene.remove(item);const drawable=item as THREE.Mesh;drawable.geometry?.dispose();const mats=drawable.material;for(const mat of Array.isArray(mats)?mats:[mats])mat?.dispose();}items.length=0;}\n  function line(a:THREE.Vector3,b:THREE.Vector3,color:number,items:THREE.Object3D[]):void {const l=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineBasicMaterial({color,depthTest:false,transparent:true,opacity:.9}));l.renderOrder=990;scene.add(l);items.push(l);}\n  function dot(p:THREE.Vector3):void {const m=new THREE.Mesh(new THREE.SphereGeometry(.18,10,10),new THREE.MeshBasicMaterial({color:0xc7ef7b,depthTest:false}));m.position.copy(p);m.renderOrder=999;scene.add(m);rulerGeometry.push(m);}\n  function reset():void {first=null;complete=false;dispose(rulerGeometry);value.textContent='—';axes.textContent='';help.textContent=mode==='base'?'Clique em um ponto da peça para medir a altura perpendicular até a baseplate.':'Clique no primeiro ponto da peça.';viewer.requestRender();}\n  function setActive(next:boolean):void {active=next;panel.hidden=!next;button.classList.toggle('active',next);button.setAttribute('aria-pressed',String(next));canvas.style.cursor=next?'crosshair':'';if(next){viewer.setTransformMode(null);viewer.setPaintToolEnabled?.(false);viewer.setIntentPaintMode(false);}reset();}\n  button.addEventListener('click',()=>setActive(!active));\n  document.getElementById('nacent-ruler-close')!.addEventListener('click',()=>setActive(false));\n  document.getElementById('nacent-ruler-clear')!.addEventListener('click',reset);\n  for(const next of ['points','base'] as const)document.getElementById('nacent-ruler-'+next)!.addEventListener('click',()=>{mode=next;for(const m of ['points','base'])document.getElementById('nacent-ruler-'+m)!.setAttribute('aria-pressed',String(m===mode));reset();});\n  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active)setActive(false);});\n  document.addEventListener('tool-panel-changed',()=>{if(active)setActive(false);});\n  function measure(clientX:number,clientY:number):void {\n    const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;\n    camera.updateMatrixWorld();const ray=new THREE.Raycaster();\n    ray.setFromCamera(new THREE.Vector2((clientX-rect.left)/rect.width*2-1,-((clientY-rect.top)/rect.height)*2+1),camera);\n    const meshes=viewer.objects.map(o=>o.mesh as unknown as THREE.Object3D);for(const mesh of meshes)mesh.updateWorldMatrix(true,false);\n    const hit=ray.intersectObjects(meshes,true)[0];\n    if(!hit){help.textContent='Clique diretamente na superfície da peça.';return;}\n    const p=hit.point.clone();\n    if(mode==='base'){reset();const base=orthogonalToBase(p);dot(p);dot(base);line(p,base,0xc7ef7b,rulerGeometry);value.textContent=p.distanceTo(base).toFixed(3)+' mm';axes.textContent='Altura perpendicular (Z) até o plano da baseplate.';help.textContent=p.y<0?'O ponto está abaixo da baseplate.':'Altura do ponto selecionado até a baseplate.';complete=true;}\n    else if(!first||complete){reset();first=p;dot(p);help.textContent='Clique no segundo ponto da peça.';}\n    else {dot(p);line(first,p,0xc7ef7b,rulerGeometry);value.textContent=first.distanceTo(p).toFixed(3)+' mm';axes.textContent=`ΔX ${Math.abs(p.x-first.x).toFixed(3)} · ΔY ${Math.abs(p.z-first.z).toFixed(3)} · ΔZ ${Math.abs(p.y-first.y).toFixed(3)} mm`;help.textContent='Distância direta entre os dois pontos. Clique para iniciar outra medição.';complete=true;}\n    viewer.requestRender();\n  }\n  // Capture before OrbitControls, selection and transform listeners consume a click.\n  canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0||e.altKey)return;gesture={x:e.clientX,y:e.clientY,pointerId:e.pointerId};canvas.setPointerCapture(e.pointerId);e.preventDefault();e.stopImmediatePropagation();},true);\n  canvas.addEventListener('pointermove',e=>{if(active&&gesture){e.preventDefault();e.stopImmediatePropagation();}},true);\n  canvas.addEventListener('pointerup',e=>{if(!active||!gesture||gesture.pointerId!==e.pointerId)return;const start=gesture;gesture=null;e.preventDefault();e.stopImmediatePropagation();if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(Math.hypot(e.clientX-start.x,e.clientY-start.y)<6)measure(e.clientX,e.clientY);},true);\n  canvas.addEventListener('pointercancel',()=>{gesture=null;},true);\n  canvas.addEventListener('click',e=>{if(active&&!e.altKey){e.preventDefault();e.stopImmediatePropagation();}},true);\n\n  function projectTags():void {const r=canvas.getBoundingClientRect();for(const tag of dimensionTags){const p=tag.position.clone().project(camera);tag.element.hidden=p.z<-1||p.z>1||Math.abs(p.x)>1.05||Math.abs(p.y)>1.05;tag.element.style.left=((p.x+1)*r.width/2)+'px';tag.element.style.top=((-p.y+1)*r.height/2)+'px';tag.element.style.transform='translate(-50%,-50%)';}}\n  function updateDimensions():void {\n    dispose(dimensionsGeometry);for(const tag of dimensionTags)tag.element.remove();dimensionTags.length=0;\n    const targets=viewer.selected.length?viewer.selected:viewer.objects;\n    const box=modelBounds(targets.map(o=>o.mesh as unknown as THREE.Object3D));\n    document.getElementById('nacent-size-scope')!.textContent=viewer.selected.length===1?'Dimensões da peça selecionada':viewer.selected.length>1?'Dimensões das peças selecionadas':'Dimensões dos modelos da plate';\n    const d=printerDimensions(box);for(const {key,input} of dimensionInputs){input.disabled=viewer.selected.length!==1||box.isEmpty()||d[key]<=0;input.value=box.isEmpty()?'':String(Number(d[key].toFixed(6)));}\n    sizeHint.textContent=viewer.selected.length===1?'Edite uma medida · Enter ou sair do campo · escala proporcional':'Selecione uma única peça para editar · escala proporcional';\n    if(box.isEmpty()){viewer.requestRender();return;}\n    const a=box.min,b=box.max,pad=Math.max(.6,box.getSize(new THREE.Vector3()).length()*.035);\n    const pairs:[THREE.Vector3,THREE.Vector3,string][]=[\n      [new THREE.Vector3(a.x,a.y-pad,a.z-pad),new THREE.Vector3(b.x,a.y-pad,a.z-pad),'Largura '+d.width.toFixed(3)+' mm'],\n      [new THREE.Vector3(b.x+pad,a.y-pad,a.z),new THREE.Vector3(b.x+pad,a.y-pad,b.z),'Comprimento '+d.length.toFixed(3)+' mm'],\n      [new THREE.Vector3(b.x+pad,a.y,b.z+pad),new THREE.Vector3(b.x+pad,b.y,b.z+pad),'Altura '+d.height.toFixed(3)+' mm']];\n    for(const [from,to,text] of pairs){line(from,to,0x89c977,dimensionsGeometry);const tag=document.createElement('span');tag.className='nacent-dimension-tag';tag.textContent=text;viewport.append(tag);dimensionTags.push({element:tag,position:from.clone().add(to).multiplyScalar(.5)});}\n    projectTags();viewer.requestRender();\n  }\n  let pending=false;function scheduleDimensions():void {if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;updateDimensions();});}\n  for(const name of ['mesh-changed','selection-changed','plate-changed'])canvas.addEventListener(name,()=>{if(active)reset();scheduleDimensions();});\n  (viewer.controls as {addEventListener:(type:string,callback:()=>void)=>void}).addEventListener('change',projectTags);\n  (viewer.transformControl as {addEventListener:(type:string,callback:()=>void)=>void}).addEventListener('objectChange',scheduleDimensions);\n  new ResizeObserver(()=>requestAnimationFrame(projectTags)).observe(canvas);\n  updateDimensions();\n}\n");
fs.writeFileSync(path.join(root,'src/core/nacent-measure-math.ts'),"import * as THREE from 'three';\n\nexport function orthogonalToBase(point:THREE.Vector3, baseY=0):THREE.Vector3 {\n  return new THREE.Vector3(point.x,baseY,point.z);\n}\n\n/** Precise world-space extrema, rather than rotating a loose local bounding box. */\nexport function modelBounds(meshes:THREE.Object3D[]):THREE.Box3 {\n  const box=new THREE.Box3();\n  for(const mesh of meshes){mesh.updateWorldMatrix(true,false);box.expandByObject(mesh,true);}\n  return box;\n}\n\n/** Viewer Y is up; printer coordinates use Z for height. All units are mm. */\nexport function printerDimensions(box:THREE.Box3):{width:number;length:number;height:number} {\n  const size=box.getSize(new THREE.Vector3());\n  return {width:size.x,length:size.z,height:size.y};\n}\n\nexport function proportionalScaleFactor(current:number,target:number):number {\n  if(!Number.isFinite(current)||current<=0||!Number.isFinite(target)||target<=0)throw Error('Informe uma dimensão maior que zero.');\n  const factor=target/current;\n  if(!Number.isFinite(factor)||factor<=0)throw Error('Confira a dimensão informada.');\n  return factor;\n}\n");
fs.writeFileSync(path.join(root,'src/nacent-measure.test.ts'),"import {describe,it,expect} from 'vitest';\nimport * as THREE from 'three';\nimport {modelBounds,printerDimensions,orthogonalToBase,proportionalScaleFactor} from '@core/nacent-measure-math';\nimport {ensureGeometryBoundsTree,refreshGeometryBoundsTree} from './geometry-bvh';\n\ndescribe('Nacent ruler and live dimensions',()=>{\n  it('editing any dimension scales all rotated model dimensions proportionally',()=>{\n    for(const key of ['width','length','height'] as const){\n      const mesh=new THREE.Mesh(new THREE.BoxGeometry(10,20,30));mesh.rotation.z=.4;\n      const before=printerDimensions(modelBounds([mesh]));\n      const factor=proportionalScaleFactor(before[key],before[key]*2.5);mesh.scale.setScalar(factor);\n      const after=printerDimensions(modelBounds([mesh]));\n      for(const axis of ['width','length','height'] as const)expect(after[axis]).toBeCloseTo(before[axis]*2.5);\n    }\n  });\n  it('invalid dimension edits never yield a destructive scale',()=>{\n    for(const target of [0,-2,NaN,Infinity])expect(()=>proportionalScaleFactor(10,target)).toThrow();\n    expect(()=>proportionalScaleFactor(0,10)).toThrow();\n  });\n  it('base distance is perpendicular, independent of horizontal offset',()=>{\n    const p=new THREE.Vector3(123,17,-250),b=orthogonalToBase(p);\n    expect(b.toArray()).toEqual([123,0,-250]);expect(p.distanceTo(b)).toBe(17);\n    expect(new THREE.Vector3(123,-2,-250).distanceTo(orthogonalToBase(new THREE.Vector3(123,-2,-250)))).toBe(2);\n  });\n  it('point-to-point measures the diagonal rather than vertical height',()=>{\n    expect(new THREE.Vector3(0,0,0).distanceTo(new THREE.Vector3(3,4,0))).toBe(5);\n  });\n  it('dimensions track scaling and map height to printer Z',()=>{\n    const m=new THREE.Mesh(new THREE.BoxGeometry(10,20,30));\n    m.scale.set(2,.5,3);m.position.set(100,50,-300);\n    expect(printerDimensions(modelBounds([m]))).toEqual({width:20,length:90,height:10});\n    m.scale.set(1,1,1);expect(printerDimensions(modelBounds([m]))).toEqual({width:10,length:30,height:20});\n  });\n  it('rotation uses transformed vertices, not transformed local box corners',()=>{\n    const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,10,0,0,0,10,0],3));\n    const m=new THREE.Mesh(geo);m.rotation.z=Math.PI/4;\n    const d=printerDimensions(modelBounds([m]));\n    expect(d.width).toBeCloseTo(10*Math.sqrt(2));expect(d.height).toBeCloseTo(10/Math.sqrt(2));\n  });\n  it('empty selections and grouped pieces do not include the plate or supports',()=>{\n    expect(modelBounds([]).isEmpty()).toBe(true);\n    const a=new THREE.Mesh(new THREE.BoxGeometry(10,10,10)),b=a.clone();b.position.x=20;\n    expect(printerDimensions(modelBounds([a,b]))).toEqual({width:30,length:10,height:10});\n  });\n  it('surface clicks remain accurate after geometry is scaled and baked',()=>{\n    const geo=new THREE.BoxGeometry(10,10,10),mesh=new THREE.Mesh(geo);\n    ensureGeometryBoundsTree(geo);geo.scale(2,2,2);geo.translate(50,15,-40);\n    refreshGeometryBoundsTree(geo);mesh.updateMatrixWorld();\n    const ray=new THREE.Raycaster(new THREE.Vector3(58,15,0),new THREE.Vector3(0,0,-1));\n    const hit=ray.intersectObject(mesh)[0];expect(hit).toBeDefined();expect(hit.point.z).toBeCloseTo(-30);\n  });\n});\n");
fs.writeFileSync(path.join(root,'src/core/nacent-history.ts'),"import * as THREE from 'three';\nimport type {SceneObject} from '../viewer-core';\nimport type {Viewer} from '../viewer';\nimport {getPillarSet,setPillarSet,type ModelPillarSet} from '../features/support-generation/pillar-store';\nimport {ensureGeometryBoundsTree} from '../geometry-bvh';\n\nfunction copyPillars(value:ModelPillarSet):ModelPillarSet {\n  return {...value,pillars:structuredClone(value.pillars),settings:{...value.settings,routeContext:undefined}};\n}\nfunction snapshotSupport(mesh:THREE.Mesh|null){\n  if(!mesh)return null;\n  return {geometry:mesh.geometry.clone(),material:(mesh.material as THREE.Material).clone(),position:mesh.position.clone(),rotation:mesh.rotation.clone(),scale:mesh.scale.clone()};\n}\nexport function captureNacentObject(obj:SceneObject){\n  return {nacentHistory:{id:obj.id,name:obj.mesh.name,supports:snapshotSupport(obj.supportsMesh),bracing:snapshotSupport(obj.bracingMesh),pillars:copyPillars(getPillarSet(obj.id))}};\n}\nexport function restoreNacentMetadata(viewer:Pick<Viewer,'scene'>,obj:SceneObject,snapshot:unknown):void {\n  const state=(snapshot as ReturnType<typeof captureNacentObject>).nacentHistory;if(!state)return;\n  obj.id=state.id;obj.mesh.userData.id=state.id;obj.mesh.name=state.name;\n  setPillarSet(state.id,copyPillars(state.pillars));\n  for(const [key,data] of [['supportsMesh',state.supports],['bracingMesh',state.bracing]] as const){\n    if(!data){obj[key]=null;continue;}\n    const geo=data.geometry.clone();ensureGeometryBoundsTree(geo);\n    const mesh=new THREE.Mesh(geo,data.material.clone());mesh.position.copy(data.position);mesh.rotation.copy(data.rotation);mesh.scale.copy(data.scale);mesh.updateMatrixWorld();\n    obj[key]=mesh;viewer.scene.add(mesh);\n  }\n  obj._cachedLocalVolume=undefined;obj._cachedLocalSupportVolume=undefined;\n}\n");
fs.writeFileSync(path.join(root,'src/nacent-history.test.ts'),"import {it,expect} from 'vitest';\nimport * as THREE from 'three';\nimport type {SceneObject} from './viewer-core';\nimport {captureNacentObject,restoreNacentMetadata} from '@core/nacent-history';\nimport {getPillarSet,clearPillarSet} from './features/support-generation/pillar-store';\nit('undo metadata preserves support geometry, stable identity and model name',()=>{\n  const original={id:'history-test',mesh:new THREE.Mesh(new THREE.BoxGeometry(10,10,10)),supportsMesh:new THREE.Mesh(new THREE.BoxGeometry(2,5,2)),bracingMesh:null,elevation:5,materialPreset:{}} as SceneObject;\n  original.mesh.name='Modelo.stl';original.supportsMesh!.position.set(12,3,4);\n  const snap=captureNacentObject(original);original.supportsMesh!.geometry.scale(2,2,2);clearPillarSet(original.id);\n  const restored={id:'temporary',mesh:original.mesh.clone(),supportsMesh:null,bracingMesh:null} as SceneObject;\n  const scene=new THREE.Scene();restoreNacentMetadata({scene},restored,snap);\n  expect(restored.id).toBe(original.id);expect(restored.mesh.name).toBe('Modelo.stl');\n  expect(restored.supportsMesh!.position.toArray()).toEqual([12,3,4]);\n  restored.supportsMesh!.geometry.computeBoundingBox();expect(restored.supportsMesh!.geometry.boundingBox!.getSize(new THREE.Vector3()).toArray()).toEqual([2,5,2]);\n  expect(getPillarSet(restored.id).pillars).toEqual(snap.nacentHistory.pillars.pillars);\n});\n");
fs.writeFileSync(path.join(root,'src/nacent-clean.ts'),"import * as THREE from 'three';\nimport type {AppContext} from '@core/types';\nimport {modelBounds} from '@core/nacent-measure-math';\nimport {estimateSlaHours} from './nacent-slicer-budget';\n\nexport function mountNacentClean(ctx:AppContext):void{\n  document.title='Nacent — Preparador de bandejas';\n  const {viewer}=ctx,sidebar=document.getElementById('sidebar')!,toolbar=document.getElementById('left-toolbar')!;\n  for(const id of ['mode-pill','orient-btn','modify-btn','surface-btn','slice-tool-btn','one-click-prepare-btn','hud-slice','hud-orient','hud-surface','clear-autosave-btn'])document.getElementById(id)?.remove();\n  const bar=document.getElementById('nacent-budget-bar')!;\n  bar.querySelector('b')!.textContent='Nacent · Preparar bandeja';bar.querySelector('span')!.textContent='Adicionar peças · Posicionar · Gerar suportes · Orçar';\n  document.getElementById('nacent-use')?.remove();\n  const use=document.getElementById('nacent-quick-use')!;use.textContent='Usar bandeja no orçamento →';\n  document.getElementById('nacent-feedback')!.textContent='Estimativa geométrica da peça + suportes. Tempo estimado pelos parâmetros de impressão.';\n  if(new URLSearchParams(location.search).has('demo'))document.getElementById('nacent-feedback')!.textContent='Demonstração isolada · esta bandeja não altera seus projetos salvos.';\n  const settings=bar.querySelector('details')!;settings.querySelector('summary')!.textContent='Tempo de impressão';\n  for(const id of ['layer-height','normal-exposure','bottom-layers','bottom-exposure','lift-height','lift-speed']){\n    const el=document.getElementById(id);const group=el?.closest('.control-group');if(group)settings.append(group);\n  }\n  for(const id of ['orientation-panel','hollow-panel','cut-panel','primitive-boolean-panel','materials-panel','paint-panel','slice-panel','layer-preview-panel','health-panel','summary-panel','footer-actions'])document.getElementById(id)?.remove();\n  settings.querySelector('small')!.textContent='Ajuste estes parâmetros à resina e à impressora. Não há fatiamento por camada neste preparador.';\n  const load=document.getElementById('load-panel')!;load.querySelector('h2')!.textContent='Adicionar peças';\n  document.getElementById('browse-stl-btn')!.textContent='＋ Adicionar STLs à bandeja';\n  const examples=load.querySelector('.sample-model-grid');if(examples){const details=document.createElement('details');details.className='nacent-examples';details.innerHTML='<summary>Modelos de exemplo</summary>';examples.before(details);details.append(examples);examples.previousElementSibling?.tagName==='H3'&&examples.previousElementSibling.remove();}\n  const list=document.createElement('section');list.id='nacent-object-list';list.innerHTML='<header><b>Peças na bandeja</b><button type=\"button\" id=\"nacent-select-all\">Selecionar todas</button></header><div id=\"nacent-object-rows\"></div><small>Ctrl ou Shift + clique para selecionar várias.</small>';load.after(list);\n  document.getElementById('nacent-select-all')!.addEventListener('click',()=>viewer.selectAll());\n  const summary=document.createElement('section');summary.id='nacent-ready-summary';sidebar.append(summary);\n  const frame=document.createElement('button');frame.type='button';frame.id='nacent-frame';frame.textContent='⊞ Enquadrar bandeja';frame.addEventListener('click',framePlate);load.append(frame);\n  function framePlate():void{\n    const box=modelBounds(viewer.objects.flatMap(o=>[o.mesh,o.supportsMesh,o.bracingMesh].filter(Boolean)) as unknown as THREE.Object3D[]);if(box.isEmpty())return;\n    const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),camera=viewer.camera as THREE.PerspectiveCamera;\n    const controls=viewer.controls as {target:THREE.Vector3;update:()=>void};\n    const dir=camera.position.clone().sub(controls.target).normalize();if(!dir.lengthSq())dir.set(1,.8,1).normalize();\n    const distance=Math.max(size.x,size.y,size.z,10)*1.5/Math.tan(THREE.MathUtils.degToRad(camera.fov??45)/2);\n    controls.target.copy(center);camera.position.copy(center).addScaledVector(dir,distance);controls.update();viewer.requestRender();\n  }\n  viewer.canvas.addEventListener('nacent-frame-plate',framePlate);\n  const symbols={translate:'<path d=\"M12 2v20M2 12h20m-14-8 4-2 4 2M8 20l4 2 4-2M4 8l-2 4 2 4m16-8 2 4-2 4\"/>',scale:'<path d=\"M14 3h7v7M21 3l-8 8M10 21H3v-7m0 7 8-8\"/><rect x=\"8\" y=\"8\" width=\"8\" height=\"8\"/>',rotate:'<path d=\"M20 7v5h-5M4 17v-5h5m10-5a8 8 0 0 0-14-2m0 12a8 8 0 0 0 14 2\"/>'};\n  for(const [mode,label] of [['translate','Mover'],['scale','Escalar'],['rotate','Girar']] as const){\n    const btn=document.createElement('button');btn.type='button';btn.id='nacent-transform-'+mode;btn.className='tool-btn nacent-transform-btn';btn.dataset.mode=mode;btn.setAttribute('aria-label',label+' peça');btn.title=label+' peça';btn.innerHTML=`<svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\">${symbols[mode]}</svg><span>${label}</span>`;\n    toolbar.append(btn);btn.addEventListener('click',()=>{ctx.showToolPanel('plate');document.querySelector<HTMLButtonElement>(`#transform-panel [data-mode=\"${mode}\"]`)?.click();toolbar.querySelectorAll('.nacent-transform-btn').forEach(b=>b.classList.toggle('active',b===btn));});\n  }\n  const plateButton=document.getElementById('plate-btn')!;plateButton.setAttribute('aria-label','Peças e bandeja');const plateLabel=plateButton.querySelector('span');if(plateLabel)plateLabel.textContent='Peças';\n  for(const id of ['plate-btn','nacent-transform-translate','nacent-transform-scale','nacent-transform-rotate','support-tool-btn','nacent-ruler-btn']){const button=document.getElementById(id);if(button)toolbar.append(button);}\n  const allowedShow=ctx.showToolPanel;ctx.showToolPanel=name=>allowedShow(name==='supports'?'supports':'plate');ctx.showToolPanel('plate');\n  function update():void{\n    const rows=document.getElementById('nacent-object-rows')!;rows.replaceChildren();\n    const selected=new Set(viewer.selected.map(o=>o.id));\n    viewer.objects.forEach((obj,index)=>{const row=document.createElement('button');row.type='button';row.className='nacent-object-row';row.setAttribute('aria-pressed',String(selected.has(obj.id)));row.textContent=`${index+1}. ${obj.mesh.name||'Peça '+(index+1)}`;row.title=obj.mesh.name||'Peça';row.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)viewer.toggleSelection(obj.id);else viewer.selectObject(obj.id);});rows.append(row);});\n    if(!viewer.objects.length)rows.textContent='Adicione um ou mais STLs.';\n    toolbar.querySelectorAll<HTMLButtonElement>('.nacent-transform-btn').forEach(b=>b.disabled=!viewer.objects.length);\n    const info=viewer.getOverallInfo();if(!info){summary.textContent='Bandeja vazia';return;}\n    const meshes=viewer.objects.flatMap(o=>[o.mesh,o.supportsMesh,o.bracingMesh].filter(Boolean)) as unknown as THREE.Object3D[];\n    const box=new THREE.Box3();for(const mesh of meshes)box.expandByObject(mesh);const spec=ctx.slicer.getPrinterSpec(),plate=ctx.project.plates.find(p=>p.id===ctx.project.activePlateId);\n    const ox=plate?.originX??0,oz=plate?.originZ??0;\n    const fits=box.min.x>=ox-spec.buildWidthMM/2-.01&&box.max.x<=ox+spec.buildWidthMM/2+.01&&box.min.z>=oz-spec.buildDepthMM/2-.01&&box.max.z<=oz+spec.buildDepthMM/2+.01&&box.min.y>=-.01&&box.max.y<=spec.buildHeightMM+.01;\n    const read=(id:string)=>Number((document.getElementById(id) as HTMLInputElement)?.value);let time='Confira os parâmetros de tempo';\n    try{const layers=Math.max(1,Math.ceil(box.max.y/read('layer-height')));time=estimateSlaHours(layers,{normalExposure:read('normal-exposure'),bottomExposure:read('bottom-exposure'),bottomLayers:read('bottom-layers'),liftHeight:read('lift-height'),liftSpeed:read('lift-speed'),retractSpeed:read('nacent-retract'),restSeconds:read('nacent-rest')}).toFixed(2)+' h estimadas';}catch{}\n    summary.innerHTML=`<b>${viewer.objects.length} peça(s) · ${time}</b><div>Peças: ${(info.modelVolume/1000).toFixed(2)} ml</div><div>Suportes: ${(info.supportVolume/1000).toFixed(2)} ml</div><strong>Total: ${((info.modelVolume+info.supportVolume)/1000).toFixed(2)} ml</strong><small class=\"${fits?'':'nacent-outside'}\">${fits?'Dentro dos limites da bandeja':'Há peças ou suportes fora da bandeja. Posicione ou reduza antes de imprimir.'}</small>`;\n  }\n  ctx.updateEstimate=update;for(const event of ['mesh-changed','selection-changed','plate-changed'])viewer.canvas.addEventListener(event,update);settings.addEventListener('change',update);\n  const style=document.createElement('style');style.textContent=`#left-toolbar .tool-btn{padding:7px 4px;min-height:45px;font-size:10px}#sidebar{width:300px;padding:12px;gap:10px}#sidebar h2{font-size:14px;margin:0 0 10px}#nacent-object-list{border:1px solid var(--border);border-radius:8px;padding:10px;margin-bottom:10px}#nacent-object-list header{display:flex;justify-content:space-between;align-items:center;font-size:11px}#nacent-object-list button,#nacent-frame{border:1px solid var(--border);background:var(--surface-2);color:var(--text);border-radius:5px;padding:6px;cursor:pointer;font:11px system-ui}#nacent-object-rows{max-height:145px;overflow:auto;margin:8px 0}.nacent-object-row{display:block;width:100%;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:4px 0}.nacent-object-row[aria-pressed=true]{background:#d0ee9b!important;color:#173329!important}#nacent-object-list small,#nacent-import-status{font-size:10px;line-height:1.5;color:var(--text-dim)}#nacent-ready-summary{border-top:1px solid var(--border);padding-top:10px;font:12px system-ui;line-height:1.7}#nacent-ready-summary b,#nacent-ready-summary strong,#nacent-ready-summary small{display:block}#nacent-ready-summary small{font-size:10px;color:var(--text-dim)}#nacent-ready-summary .nacent-outside{color:#df824e}#nacent-frame{width:100%;margin-top:7px}#load-panel>p,#load-panel>h3{display:none}.nacent-examples{margin-top:8px;font-size:10px}#edit-panel .badge,#group-btn,#ungroup-btn,#fill-btn,#clear-btn,#support-density-group{display:none}#nacent-budget-bar details[open]{max-height:75vh;overflow:auto;right:230px;z-index:10001}#nacent-budget-bar .control-group{margin:8px 0}#nacent-budget-bar .control-group label{font-size:11px;margin:0}#nacent-budget-bar .control-group input{float:right}#nacent-budget-bar details{font-size:11px}#nacent-dimensions{max-width:calc(100% - 125px)}#bottom-bar .hud-section:not(#hud-plate):not(#hud-supports){display:none!important}#nacent-import-status:empty{display:none}`;document.head.append(style);\n  update();\n  style.textContent+='#sidebar{min-width:300px;flex-basis:300px}#sidebar .panel{width:100%;padding:7px 0}#sidebar .control-group{margin-bottom:9px}#sidebar .task-fields{gap:7px}.sidebar-collapse-btn{right:300px}#nacent-ready-summary{position:sticky;bottom:0;background:var(--surface);padding:9px 0;margin-top:auto}#left-toolbar{gap:5px}#supports-panel .advanced-group{margin:6px 0}.adv{display:none!important}';\n  document.getElementById('support-all-btn')!.textContent='Gerar em todas as peças';\n  for(const [id,text] of [['move-x','X largura (mm)'],['move-y','Z altura (mm)'],['move-z','Y comprimento (mm)'],['rotate-x','Giro adicional X (°)'],['rotate-y','Giro adicional Z (°)'],['rotate-z','Giro adicional Y (°)']] as const){const input=document.getElementById(id);input?.setAttribute('aria-label',text);const label=input?.closest('label');if(label?.firstChild?.nodeType===Node.TEXT_NODE)label.firstChild.textContent=text+' ';}\n  for(const id of ['scale-x','scale-y','scale-z']){const group=document.getElementById(id)?.closest<HTMLElement>('.control-group');if(group)group.style.display='none';}\n  const relative=document.querySelector<HTMLElement>('#transform-scale-fields .field-heading');if(relative)relative.style.display='none';\n  const scaleButton=document.querySelector('#transform-panel [data-mode=\"scale\"]');if(scaleButton)scaleButton.textContent='Escalar';\n  style.textContent+='#transform-move-fields:not([hidden]),#transform-rotate-fields:not([hidden]),#transform-scale-fields:not([hidden]){display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:9px 0}#transform-scale-fields>.field-heading,#transform-scale-fields>.control-group:first-child{grid-column:1/-1}#transform-panel .transform-fields .control-group{margin:0}#transform-panel .transform-fields label{display:flex;flex-direction:column;align-items:stretch;gap:5px;font-size:10px}#transform-panel .transform-fields input[type=number]{width:100%;min-width:0;box-sizing:border-box;text-align:left;padding:5px}#transform-panel .field-heading{font-size:11px;margin:9px 0 6px}#edit-panel .btn{font-size:11px;padding:7px}';\n}\n");
fs.writeFileSync(path.join(root,'src/nacent-lite-slicer.ts'),"import type {LegacySlicer} from '@core/legacy-types';\nimport type {PrinterSpec} from '@core/types';\nimport printersData from './data/printers.json';\nexport const PRINTERS=printersData as Record<string,PrinterSpec>;\n/** Budget preparation uses the 3D viewport only: no slicing canvas or GPU layer buffers. */\nexport class Slicer implements LegacySlicer{\n  private printer=PRINTERS['saturn-3-ultra'];\n  setPrinter(key:string):void{if(PRINTERS[key])this.printer=PRINTERS[key];}\n  getPrinterSpec():PrinterSpec{return this.printer;}\n  uploadGeometry():void{}\n  setInstances():void{}\n  getLayerCount():number{return 0;}\n  renderLayer():Uint8Array{throw Error('Esta ferramenta prepara bandejas para orçamento.');}\n  async slice():Promise<null>{throw Error('Use a estimativa da bandeja, sem fatiar.');}\n}\n");
fs.writeFileSync(path.join(root,'src/features/app-shell/file-handling.ts'),"import type {AppContext} from '@core/types';\nimport {formatRegistry} from '@core/format-registry';\nimport {listen} from './utils';\n\nexport function mountFileHandling(ctx:AppContext):void{\n  const input=document.getElementById('stl-input') as HTMLInputElement|null,browse=document.getElementById('browse-stl-btn'),container=document.getElementById('viewport-container'),samples=document.querySelector('.sample-model-grid');\n  const status=document.createElement('p');status.id='nacent-import-status';status.setAttribute('role','status');browse?.after(status);\n  if(input){input.accept=formatRegistry.getImporterAcceptString();input.multiple=true;}\n  let queue=Promise.resolve();\n  function enqueue(files:File[]):void{\n    if(!files.length)return;const plateId=ctx.project.activePlateId;\n    queue=queue.then(async()=>{\n      const added:string[]=[],errors:string[]=[];let saved=false;\n      for(let i=0;i<files.length;i++){\n        const file=files[i],importer=formatRegistry.getImporterForFile(file.name);\n        if(!importer){errors.push(file.name+' (formato não suportado)');continue;}\n        try{\n          if(ctx.project.activePlateId!==plateId)throw Error('A bandeja ativa mudou. Importe novamente nela.');\n          ctx.showProgress(`Loading ${file.name}...`);status.textContent=`Adicionando ${i+1}/${files.length}: ${file.name}`;\n          const geometry=await importer.parse(await file.arrayBuffer(),file.name);\n          if(!geometry.positions.length||geometry.positions.some(v=>!Number.isFinite(v)))throw Error('Geometria vazia ou inválida');\n          if(ctx.project.activePlateId!==plateId)throw Error('A bandeja ativa mudou.');\n          if(!saved){ctx.viewer._saveUndoState?.();saved=true;}\n          ctx.viewer.loadParsedGeometry(geometry);\n          const obj=ctx.viewer.selected.at(-1);if(obj){obj.mesh.name=file.name;added.push(obj.id);}\n          ctx.clearActivePlateSlice();ctx.updateEstimate();ctx.viewer.requestRender();\n          await new Promise<void>(resolve=>setTimeout(resolve,0));\n        }catch(error){errors.push(file.name+': '+(error instanceof Error?error.message:'Não foi possível carregar'));}\n      }\n      if(added.length){ctx.viewer.selectObjects(added);ctx.showToolPanel('plate');ctx.viewer.canvas?.dispatchEvent(new CustomEvent('nacent-frame-plate'));ctx.scheduleProjectAutosave();}\n      status.textContent=`${added.length} peça(s) adicionada(s) à mesma bandeja.${errors.length?' Falha: '+errors.join('; '):' Selecione uma peça na lista para editar.'}`;\n      ctx.hideProgress();\n    }).catch(error=>{status.textContent=String(error);ctx.hideProgress();});\n  }\n  listen(browse,'click',()=>input?.click());\n  listen(input,'change',()=>{const files=Array.from(input?.files??[]);if(input)input.value='';enqueue(files);});\n  listen(container,'dragover',e=>{e.preventDefault();container?.classList.add('drag-over');});\n  listen(container,'dragleave',()=>container?.classList.remove('drag-over'));\n  listen(container,'drop',e=>{e.preventDefault();container?.classList.remove('drag-over');enqueue(Array.from((e as DragEvent).dataTransfer?.files??[]));});\n  listen(samples,'click',e=>{const card=(e.target as HTMLElement).closest<HTMLElement>('[data-model]');const name=card?.dataset.model;if(!name)return;\n    fetch(`${import.meta.env.BASE_URL}models/${name}.stl`).then(r=>{if(!r.ok)throw Error('Não foi possível carregar o exemplo');return r.arrayBuffer();}).then(buffer=>enqueue([new File([buffer],name+'.stl')])).catch(error=>{status.textContent=String(error);});\n  });\n}\n");
fs.writeFileSync(path.join(root,'src/core/nacent-plate-layout.ts'),"import * as THREE from 'three';\nimport type {ViewerCore,SceneObject} from '../viewer-core';\nexport type Footprint={minX:number;maxX:number;minZ:number;maxZ:number};\nexport function findFreePosition(width:number,depth:number,occupied:Footprint[],bedWidth:number,bedDepth:number,gap=3):{x:number;z:number;fits:boolean}{\n  const xs=[0,-bedWidth/2+width/2,bedWidth/2-width/2],zs=[0,-bedDepth/2+depth/2,bedDepth/2-depth/2];\n  for(const b of occupied){xs.push(b.minX-width/2-gap,b.maxX+width/2+gap);zs.push(b.minZ-depth/2-gap,b.maxZ+depth/2+gap);}\n  const candidates=xs.flatMap(x=>zs.map(z=>({x,z}))).sort((a,b)=>Math.hypot(a.x,a.z)-Math.hypot(b.x,b.z));\n  for(const {x,z} of candidates){const b={minX:x-width/2,maxX:x+width/2,minZ:z-depth/2,maxZ:z+depth/2};\n    if(b.minX < -bedWidth/2-.001||b.maxX>bedWidth/2+.001||b.minZ < -bedDepth/2-.001||b.maxZ>bedDepth/2+.001)continue;\n    if(occupied.every(o=>b.maxX+gap<=o.minX+.001||b.minX-gap>=o.maxX-.001||b.maxZ+gap<=o.minZ+.001||b.minZ-gap>=o.maxZ-.001))return{x,z,fits:true};\n  }\n  return{x:Math.max(bedWidth/2,...occupied.map(b=>b.maxX))+gap+width/2,z:0,fits:false};\n}\nexport function placeNewModel(core:ViewerCore,obj:SceneObject):void{\n  if(core.objects.length<2||!core.printer)return;\n  const origin=core.getActivePlateOrigin(),bounds=new THREE.Box3().setFromObject(obj.mesh),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());\n  const occupied=core.objects.filter(o=>o!==obj).map(o=>{const b=new THREE.Box3().setFromObject(o.mesh);for(const m of [o.supportsMesh,o.bracingMesh])if(m)b.expandByObject(m);return{minX:b.min.x-origin.x,maxX:b.max.x-origin.x,minZ:b.min.z-origin.z,maxZ:b.max.z-origin.z};});\n  const printer=core.printer as {buildWidthMM:number;buildDepthMM:number};\n  const next=findFreePosition(size.x,size.z,occupied,printer.buildWidthMM,printer.buildDepthMM);\n  obj.mesh.position.x+=origin.x+next.x-center.x;obj.mesh.position.z+=origin.z+next.z-center.z;obj.mesh.updateMatrixWorld(true);\n}\n");
fs.writeFileSync(path.join(root,'src/nacent-multi-model.test.ts'),"import {describe,it,expect,vi} from 'vitest';\nimport * as THREE from 'three';\nimport {findFreePosition} from '@core/nacent-plate-layout';\nimport {loadParsedGeometry} from './viewer-core-models';\nimport type {ViewerCore,SceneObject} from './viewer-core';\nimport {mountFileHandling} from './features/app-shell/file-handling';\nimport type {AppContext} from '@core/types';\nimport './formats';\nimport {Viewer} from './viewer';\n\ndescribe('multiple models on one plate',()=>{\n  it('moving X keeps height unchanged; plain numeric rotations stay finite and preserve bed elevation',()=>{\n    const mesh=new THREE.Mesh(new THREE.BoxGeometry(10,10,10));mesh.position.y=5;\n    const obj={id:'transform',mesh,supportsMesh:null,bracingMesh:null,elevation:0,materialPreset:{}} as SceneObject;\n    const fake={selected:[obj],getSelectionWorldCenter:()=>new THREE.Box3().setFromObject(mesh).getCenter(new THREE.Vector3()),_getSelectionBounds:()=>new THREE.Box3().setFromObject(mesh),_applyMatrixToSelection:(m:THREE.Matrix4)=>{mesh.applyMatrix4(m);mesh.updateMatrixWorld();},_bakeTransform:vi.fn(),clearSupports:vi.fn()} as unknown as Viewer;\n    Viewer.prototype.translateSelectionTo.call(fake,new THREE.Vector3(30,5,0));\n    expect(new THREE.Box3().setFromObject(mesh).getCenter(new THREE.Vector3()).toArray()).toEqual([30,5,0]);\n    Viewer.prototype.rotateSelectionBy.call(fake,{x:Math.PI/4,y:0,z:0} as THREE.Euler);\n    const bounds=new THREE.Box3().setFromObject(mesh);expect(bounds.min.y).toBeCloseTo(0);expect(Number.isFinite(bounds.max.y)).toBe(true);\n    expect(bounds.getCenter(new THREE.Vector3()).x).toBeCloseTo(30);\n  });\n  it('places three imported models apart and keeps hit testing accurate after shifting mesh origins',()=>{\n    const objects:SceneObject[]=[],core={objects,selected:[] as SceneObject[],scene:new THREE.Scene(),defaultMaterialPreset:{},printer:{buildWidthMM:218.88,buildDepthMM:122.88},canvas:document.createElement('canvas'),camera:new THREE.PerspectiveCamera(),controls:{target:new THREE.Vector3(),update:vi.fn()},getActivePlateOrigin:()=>new THREE.Vector3(50,0,20),selectObject(id:string){core.selected=[objects.find(o=>o.id===id)!];}} as unknown as ViewerCore;\n    const geo=new THREE.BoxGeometry(10,10,10).toNonIndexed();\n    const parsed={positions:geo.attributes.position.array as Float32Array,normals:geo.attributes.normal.array as Float32Array,triangleCount:12};\n    for(let i=0;i<3;i++)loadParsedGeometry(core,parsed);\n    expect(objects).toHaveLength(3);\n    const boxes=objects.map(o=>new THREE.Box3().setFromObject(o.mesh));\n    expect(boxes[0].intersectsBox(boxes[1])).toBe(false);expect(boxes[1].intersectsBox(boxes[2])).toBe(false);\n    boxes.forEach((b,i)=>{const c=b.getCenter(new THREE.Vector3());const ray=new THREE.Raycaster(new THREE.Vector3(c.x,100,c.z),new THREE.Vector3(0,-1,0));expect(ray.intersectObject(objects[i].mesh)[0]?.point.y).toBeCloseTo(10);});\n    expect(boxes[0].getCenter(new THREE.Vector3()).x).toBeCloseTo(50);\n  });\n  it('never silently overlaps a full plate or shrinks a large incoming model',()=>{\n    const next=findFreePosition(10,10,[{minX:-10,maxX:10,minZ:-10,maxZ:10}],20,20);\n    expect(next.fits).toBe(false);expect(next.x).toBeGreaterThan(10);\n    expect(findFreePosition(400,300,[],218.88,122.88).fits).toBe(false);\n  });\n  it('imports every file sequentially, tolerates a corrupt file and permits selecting the same file again',async()=>{\n    document.body.innerHTML='<input id=\"stl-input\" type=\"file\"><button id=\"browse-stl-btn\"></button><div id=\"viewport-container\"></div>';\n    const selected:unknown[]=[];let concurrent=0,maxConcurrent=0,loaded=0;\n    const viewer={selected,loadParsedGeometry:vi.fn(()=>{loaded++;selected.splice(0,selected.length,{id:'model-'+loaded,mesh:{name:''}});}),_saveUndoState:vi.fn(),selectObjects:vi.fn(),requestRender:vi.fn()};\n    const ctx={viewer,project:{activePlateId:'plate'},showProgress:vi.fn(),hideProgress:vi.fn(),clearActivePlateSlice:vi.fn(),updateEstimate:vi.fn(),showToolPanel:vi.fn(),scheduleProjectAutosave:vi.fn()} as unknown as AppContext;\n    const text='solid cube\\nfacet normal 0 0 1\\nouter loop\\nvertex 0 0 0\\nvertex 1 0 0\\nvertex 0 1 0\\nendloop\\nendfacet\\nendsolid cube';\n    const file=(name:string,body=text)=>({name,arrayBuffer:async()=>{concurrent++;maxConcurrent=Math.max(maxConcurrent,concurrent);await new Promise(r=>setTimeout(r,2));concurrent--;return new TextEncoder().encode(body).buffer;}} as File);\n    mountFileHandling(ctx);const input=document.getElementById('stl-input') as HTMLInputElement;\n    Object.defineProperty(input,'files',{value:[file('first.stl'),file('broken.stl','broken'),file('last.stl')],configurable:true});input.dispatchEvent(new Event('change'));\n    await vi.waitFor(()=>expect(loaded).toBe(2));expect(maxConcurrent).toBe(1);expect(viewer._saveUndoState).toHaveBeenCalledTimes(1);expect(input.multiple).toBe(true);\n    Object.defineProperty(input,'files',{value:[file('first.stl')],configurable:true});input.dispatchEvent(new Event('change'));await vi.waitFor(()=>expect(loaded).toBe(3));\n  });\n});\n");
